// `import` becomes `#include`, and the header's 1.x functions are still callable from the migrated file.
#include "MigrateShared.dsh"

/// @name DreamShaderTests/Migrate/M_MgImport
export void M_MgImport(inout material Base)
{
    float3 Color = float3(0, 0, 0);
    float3 Tinted = float3(0, 0, 0);
    ApplyTint(float3(1.0, 1.0, 1.0), float3(1.0, 0.5, 0.25), Tinted);
    Color = Tinted * Luma(Tinted);
    Base.EmissiveColor = Color;
}
